import{z as o,x as B,o as t,c as p,q as E,j as s,D as e,d as n,s as r,S as l}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"成交到达强度","description":"","frontmatter":{"title":"成交到达强度","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hawkes-trades.md","filePath":"quant/hawkes-trades.md","lastUpdated":1791413859000}'),A={name:"quant/hawkes-trades.md"};function m(d,a,h,u,_,b){const i=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=E('<h1 id="成交到达强度" tabindex="-1">成交到达强度 <a class="header-anchor" href="#成交到达强度" aria-label="Permalink to &quot;成交到达强度&quot;">​</a></h1><div class="epigraph"><p>一笔成交会抬高随后成交的瞬时强度：市场不是在日历上以常数速率抛硬币，而是在已经发生的跳动上自我激励。</p><footer>—— 据 Hawkes, Spectra of some self-exciting and mutually exciting point processes, Biometrika, 1971；微观结构中的自激到达见 Bacry, Mastromatteo and Muzy 的综述</footer></div><p><a href="/quant/queue-imbalance-alpha">上一课</a>把队列不平衡写成短窗、事件时间上的存量 \\(I\\)，预测下一跳几何；它与 OFI 共线，一个是状态、一个是流量。缺口是到达时钟：成交成串到来，常数泊松会把依赖写进「知情强度」，识别偏掉；要描述过去事件如何抬高现在的到达率，需要强度过程。本课钉 Hawkes 成交点过程：核、分支比，以及和毒性仪表的时钟关系。不重讲 \\(I\\) 的选边用法。后课微价格默认成串是统计依赖，不是一份误导脚本。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>队列不平衡是存量状态，解释不了成交为何成串。泊松过程的强度 \\(\\lambda\\) 为常数，事件独立，等待时间是指数。真实成交不是这样：一笔大单之后往往紧跟着一串同向或反向的小单，算法切片、排队补量、以及价格移动引发的止损，都会在短时间内抬高到达率。用常数泊松去估 PIN 式的到达，等于把成串到来的依赖写进「知情强度 \\(\\mu\\)」，识别会偏。问题是：能否把强度写成历史事件的显式函数，使成串成为模型的一部分，而不是残差里的谜。</p><p>双向市场还需要相互激励：主动买是否抬高随后主动卖的强度（回弹、做市补货），还是主要抬高随后主动买（动量、切片）。这是多元 Hawkes 的问题。日历效应——开盘强度高、午间低——则要求基线强度 \\(\\mu(t)\\) 随墙钟变化。点过程必须同时容纳内生反馈与外生日历。</p><h3 id="自激核与分支比" tabindex="-1">自激核与分支比 <a class="header-anchor" href="#自激核与分支比" aria-label="Permalink to &quot;自激核与分支比&quot;">​</a></h3><p>一维线性 Hawkes 的强度为</p> \\[\\lambda(t)=\\mu+\\int_{(-\\infty,t)}\\phi(t-s)\\,\\mathrm{d}N_s=\\mu+\\sum_{t_i\\lt t}\\phi(t-t_i), \\]<p>其中 \\(N\\) 是计数过程，\\(\\phi\\ge 0\\) 是核。指数核 \\(\\phi(u)=\\alpha e^{-\\beta u}\\) 最常用，强度在每笔成交后跳上 \\(\\alpha\\)，再以 \\(\\beta\\) 衰减。稳定性要求分支比 \\(n=\\int_0^\\infty\\phi(u)\\,\\mathrm{d}u\\lt 1\\)：\\(n\\) 是一笔事件平均触发的「后代」事件数，\\(n\\to 1\\) 表示内生反馈接近临界，一小段外生流可以引发长串余震。Filimonov 与 Sornette 曾用接近 1 的分支比讨论市场内生性；估计对核的误设与短样本很敏感，不能把某日 \\(\\hat n\\approx 1\\) 直接写成「即将崩盘」。</p><p><span class="marginnote">分支比可以类比传染病的 \\(R_0\\)：\\(n=0.3\\) 意味着平均每笔成交只「传染」出 0.3 笔后续成交，串很快熄灭；\\(n\\) 逼近 1 则像 \\(R_0\\) 逼近 1 的疫情，一簇外生事件就能引发长尾余震。数字实例：指数核 \\(\\phi(u)=\\alpha e^{-\\beta u}\\) 下 \\(n=\\alpha/\\beta\\)，估得 \\(\\alpha=0.8\\)、\\(\\beta=2\\) 时 \\(n=0.4\\)，离临界还很远。</span></p><p><span class="marginnote">Hawkes 的「自激」是条件强度上升，不是价格一定沿同一方向走。同向切片与反向补货都可以抬高成交计数。要把方向放进模型，应用带标记的点过程或买卖分开的二元 Hawkes。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据用成交时间戳（最好是交易所匹配引擎时间），清洗错单见 <a href="/quant/outlier-trades">异常成交</a>。估计可用对数似然</p> \\[\\sum_i\\log\\lambda(t_i)-\\int_0^T\\lambda(t)\\,\\mathrm{d}t, \\]<p>指数核有递归，可避免对历史双重循环。基线 \\(\\mu\\) 可成分段常数（按开盘、上午、下午）或用样条。诊断看残差过程 \\(\\Lambda(t)=\\int_0^t\\lambda\\)：若模型正确，\\(\\Lambda(t_i)\\) 应接近单位速率泊松。只报告样本内似然不够。</p><p><span class="marginnote">残差诊断翻译成大白话：把「模型认为事件该有多密」累加成一把时间尺 \\(\\Lambda(t)\\)，再用这把尺去量真实到达时刻；量出来若像标准泊松一样随机，模型就过关。若残差里仍有规律（比如每到开盘总偏大），说明基线 \\(\\mu(t)\\) 没把日历效应吃干净，而不是核错了。</span></p><p>买卖分开时，核是矩阵 \\(\\phi_{ij}\\)：\\(j\\) 类事件对 \\(i\\) 类强度的激励。对角占优表示切片与动量；反对角占优表示反向成交、做市或回跳。与 OFI 对照：Hawkes 解释<strong>何时</strong>发生事件，OFI 解释事件的<strong>符号净额如何移价</strong>。可以先用 Hawkes 滤出强度，再在高强度区间估 OFI 的 \\(\\beta\\)，看冲击是否随活跃度变陡。</p><h3 id="成交时钟上的强度而不是日历秒" tabindex="-1">成交时钟上的强度而不是日历秒 <a class="header-anchor" href="#成交时钟上的强度而不是日历秒" aria-label="Permalink to &quot;成交时钟上的强度而不是日历秒&quot;">​</a></h3><p>强度 \\(\\lambda(t)\\) 的自变量仍是墙钟，因为它要谈单位时间的到达率；但「一步」的经济含义更接近事件。VPIN 用成交量切桶，Hawkes 用时间衰减核，二者都在成交加速时自动加密采样。差别是：VPIN 把方向不平衡当毒性；Hawkes 即使不分方向也能描述成串。把 Hawkes 强度当毒性会混类别：开盘的高 \\(\\lambda\\) 多半是机制，不是知情。毒性应在强度条件之上再看方向持续，或直接用 OFI、VPIN。</p><p>核的时间尺度必须匹配问题。算法切片的自激在毫秒到秒；公告后的余震在分钟；日度再入不适合用同一个 \\(\\beta\\)。跨尺度叠加可用若干指数核之和，或幂律核；后者更慢、更难估，也更容易把趋势写进内生性。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>内生机制：一笔主动成交改变队列与中点，引发撤单、补单、止损与切片的下一笔，于是 \\(N\\) 的历史进入 \\(\\lambda\\)。这是限价簿状态机的统计压缩，不必指定哪一类参与者。外生机制：公告、宏观印记、指数再平衡在 \\(\\mu(t)\\) 里抬高全体到达，即使没有自激也会成串。识别二者靠核：外生脉冲之后若 \\(\\lambda\\) 很快回到基线，串来自 \\(\\mu\\)；若衰减符合 \\(\\phi\\) 且分支比稳定，串来自反馈。</p>',23)),(t(),s(l,null,{default:e(()=>[r(i,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%A7%82%E5%AF%9F%E5%88%B0%E4%B8%80%E4%B8%B2%E5%AF%86%E9%9B%86%E6%88%90%E4%BA%A4%22%5D%20--%3E%20A%7B%22%E8%84%89%E5%86%B2%E5%90%8E%E5%BC%BA%E5%BA%A6%E5%A6%82%E4%BD%95%E5%9B%9E%E8%90%BD%3F%22%7D%0A%20%20A%20--%3E%7C%22%E7%9E%AC%E9%97%B4%E8%B7%8C%E5%9B%9E%E5%9F%BA%E7%BA%BF%20%CE%BC%22%7C%20Ex%5B%22%E5%A4%96%E7%94%9F%E6%88%90%E4%B8%B2%3A%20%E5%85%AC%E5%91%8A%20%2F%20%E5%86%8D%E5%B9%B3%E8%A1%A1%2C%20%E6%94%BE%E8%BF%9B%20%CE%BC(t)%22%5D%0A%20%20A%20--%3E%7C%22%E6%8C%89%E6%A0%B8%20%CF%86%20%E6%8C%87%E6%95%B0%E8%A1%B0%E5%87%8F%22%7C%20En%5B%22%E5%86%85%E7%94%9F%E6%88%90%E4%B8%B2%3A%20%E5%8F%8D%E9%A6%88%E9%93%BE%E5%9C%A8%E8%B5%B7%E4%BD%9C%E7%94%A8%22%5D%0A%20%20En%20--%3E%20B%7B%22%E5%88%86%E6%94%AF%E6%AF%94%20n%20%E9%80%BC%E8%BF%91%201%3F%22%7D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20Warn%5B%22%E6%8E%A5%E8%BF%91%E4%B8%B4%E7%95%8C%3A%20%E6%8A%A5%E7%BD%AE%E4%BF%A1%E5%8C%BA%E9%97%B4%2C%20%E5%8B%BF%E6%96%AD%E8%A8%80%E5%B4%A9%E7%9B%98%22%5D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20Ok%5B%22%E5%B8%B8%E8%A7%84%E8%87%AA%E6%BF%80%3A%20%E7%94%A8%E6%A0%B8%20%CF%86%20%E6%8F%8F%E8%BF%B0%E5%8D%B3%E5%8F%AF%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p><span class="marginnote">常见误区：初学者容易把「成交成串」直接解读为「有知情人在连续出手」。实际上算法切片把母单拆成小单、价格变动触发止损单，都会在没有任何私有信息的情况下制造成串；先分清内生还是外生，再谈信息。</span></p><p>与信息模型的接口：Glosten–Milgrom 与 PIN 假设到达是（混合）泊松，事件独立。Hawkes 破坏独立，PIN 的日度加总或许仍可用中心极限，但把日内强度当成常数 \\(\\varepsilon,\\mu\\) 会错。知情交易可以表现为某一方向的自激上升，但非知情的算法切片看起来一样。因此不能把 \\(\\hat\\alpha\\) 叫做知情到达率。Kyle 的连续拍卖里噪声是布朗流，也没有自激；经验 \\(\\lambda\\) 若在高强度区间更大，说明深度随到达加速而消耗，冲击模型应条件于 \\(\\lambda(t)\\)。</p><h3 id="内生性、公告与虚假临界" tabindex="-1">内生性、公告与虚假临界 <a class="header-anchor" href="#内生性、公告与虚假临界" aria-label="Permalink to &quot;内生性、公告与虚假临界&quot;">​</a></h3><p>分支比接近 1 的估计，对删失（开盘前没有足够历史）、对把公告放进自激核、对采样空洞都敏感。把周末当成高强度衰减的一部分，会扭曲 \\(\\beta\\)。稳健做法是：交易时段内估计、公告窗单独放进 \\(\\mu(t)\\)、报告 \\(n\\) 的置信区间而不是点值叙事。市场「临界」是一个吸引人的隐喻，不是 Hawkes 似然能够单独证实的交易信号。</p><p>冰山补量会在显示块耗尽后制造规则间隔的限价到达，点过程里出现近似周期性的激励。这会让指数核误把制度性补量当成自激。研究上可用标记（是否紧挨着同价位耗尽）把这类到达从核里分出来。同样，这是设定检验，不是教人设置补量间隔以伪装成自然流。</p><p><span class="marginnote">强度模型解释到达，不解释谁知情。要谈毒性，需要方向、实现价差或 PIN/VPIN 一类不平衡对象。Hawkes 可以当时钟与条件变量，不能当信息不对称的充分统计。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>线性 Hawkes 不允许抑制（\\(\\phi\\) 为负）或硬性不应期，而真实簿在撮合间隔、自成交防范上有短不应期。非线性 Hawkes、带状态依赖的强度（依赖 \\(I_1\\) 或价差）更贴近，更难估。多元过程维数随事件类型爆炸：成交、增、撤两侧已是六维。估计应先从买卖成交二维做起。</p><p>不要在集合竞价的离散匹配上套连续强度。不要用日历等间隔去拟合 Hawkes 再抱怨拟合差——点过程的似然建立在真实到达时刻上。A 股的午休要把过程断开，否则午间空洞被核解释成强衰减。长期记忆若存在，指数核只是短时近似。</p><p><span class="marginnote">把模拟出来的 Hawkes 路径直接当回测成交，会低估滑点的状态依赖：真实冲击还依赖当时深度与 OFI，而标准 Hawkes 不包含价格。价格标记的联合模型才谈得上执行仿真。</span></p>',10)),(t(),s(l,null,{default:e(()=>[r(i,{id:"mermaid-94",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E5%8E%86%E5%8F%B2%E6%88%90%E4%BA%A4%20N%22%5D%20--%3E%20Phi%5B%22%E6%A0%B8%20%CF%86%20%E5%8A%A0%E6%9D%83%22%5D%0A%20%20Mu%5B%22%E5%9F%BA%E7%BA%BF%20%CE%BC(t)%3A%20%E6%97%A5%E5%8E%86%20%2F%20%E5%85%AC%E5%91%8A%22%5D%20--%3E%20Lam%5B%22%E5%BC%BA%E5%BA%A6%20%CE%BB(t)%22%5D%0A%20%20Phi%20--%3E%20Lam%0A%20%20Lam%20--%3E%20Arr%5B%22%E4%B8%8B%E4%B8%80%E6%AC%A1%E5%88%B0%E8%BE%BE%22%5D%0A%20%20Arr%20--%3E%20N%0A%20%20Arr%20--%3E%20Dir%5B%22%E8%8B%A5%E5%B8%A6%E6%96%B9%E5%90%91%3A%20%E8%BF%9B%E5%85%A5%20OFI%20%2F%20VPIN%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>成交到达是自激点过程：Hawkes 强度 \\(\\lambda(t)=\\mu+\\int\\phi\\,\\mathrm{d}N\\)，分支比 \\(n=\\int\\phi\\) 度量内生反馈。</li><li>似然在真实时间戳上估计；残差过程应接近单位泊松；买卖应用多元核分开。</li><li>自激解释成串，不自动等于知情；毒性还要方向与事后价差。</li><li>公告应放进基线，避免把外生脉冲估成临界分支比。</li><li>冰山式规则补量会污染核，检测属于设定诊断。</li><li>出处：Hawkes, <em>Biometrika</em>, 1971；市场微观结构中的综述见 Bacry, Mastromatteo and Muzy；内生性估计见 Filimonov and Sornette 及相关讨论。</li></ul>',2))])}const k=o(A,[["render",m]]);export{c as __pageData,k as default};
